"use client";

import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Bold retail Slider: a 0.25rem grey hairline whose filled range is flat
 * black, the price filter's bar. Each thumb is a black circle ringed in white
 * on the small thumb shadow, and it grows a little while dragged. Pass an
 * array value for a range; the slider renders one thumb per value.
 */
const Slider = React.forwardRef<
  HTMLDivElement,
  WithClassName<SliderPrimitive.Root.Props>
>(({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
  const _values = Array.isArray(value)
    ? value
    : Array.isArray(defaultValue)
      ? defaultValue
      : [min];

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      ref={ref}
      thumbAlignment="edge"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn(
        "relative w-full data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <SliderPrimitive.Control className="relative flex h-6 w-full touch-none select-none items-center">
        <SliderPrimitive.Track
          data-slot="slider-track"
          className="relative h-1 w-full grow overflow-hidden rounded-full bg-border"
        >
          <SliderPrimitive.Indicator
            data-slot="slider-range"
            className="rounded-full bg-primary"
          />
        </SliderPrimitive.Track>
        {Array.from({ length: _values.length }, (_, index) => (
          <SliderPrimitive.Thumb
            data-slot="slider-thumb"
            key={index}
            className={cn(
              "block size-5 shrink-0 cursor-grab rounded-full border-2 border-background bg-primary shadow-(--shadow-thumb)",
              "transition-[scale] duration-fast ease-out active:cursor-grabbing data-[dragging]:scale-110 motion-reduce:transition-none",
              "has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring has-[:focus-visible]:ring-offset-2 has-[:focus-visible]:ring-offset-background",
              "data-[disabled]:pointer-events-none",
            )}
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  );
});
Slider.displayName = "Slider";

export { Slider };
